#!/usr/bin/env python3
"""Deliver a proved mirror of canonical master; never execute the PR's code."""
from __future__ import annotations

import argparse
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys

REPO = "cirwel/unitares-governance-plugin"
SOURCE = "https://github.com/cirwel/unitares.git"
BRANCH = "auto/plugin-skill-sync"
MANIFEST = "SKILLS_MANIFEST.sha256"
HEADER = (
    "# Canonical fingerprint of unitares/skills/ — generated by\n"
    "# scripts/dev/skills_manifest.py. Do not hand-edit; run the script.\n"
    "# Consumers (e.g. the plugin mirror) verify their copy against this file.\n"
)


# A stuck mirror used to show only in this workflow's step summary: #402 sat
# red for about 21 hours with nothing telling anyone. One open issue now
# carries it, found by this marker, and is closed when the mirror lands.
STUCK_LABEL = "ci-finding"
STUCK_MARKER = "<!-- finding-fingerprint: skill-mirror-stuck -->"
STUCK_TITLE = "Skill mirror delivery is stuck"
HOLD_LABELS = ("automerge-hold", "do-not-merge", "governance-sensitive")
# Scheduled delivery runs hourly, and pending CI or a moved ref clears within
# one or two runs. A head still held after this long is not clearing by itself.
STUCK_AFTER_SECONDS = 3 * 3600


class Hold(Exception):
    """The automation cannot establish that this PR is ready to deliver."""


class Stuck(Hold):
    """A hold that later runs cannot clear; it needs a change from someone."""


class Vetoed(Hold):
    """A maintainer placed the hold on purpose; it is not reported as stuck."""


def git(*args: str) -> bytes:
    result = subprocess.run(["git", *args], capture_output=True, check=False)
    if result.returncode:
        raise Hold("Git verification failed; no merge attempted")
    return result.stdout


def api(path: str, method: str = "GET", body=None):
    command = ["gh", "api", "--method", method, f"repos/{REPO}/{path}"]
    if body is not None:
        command += ["--input", "-"]
    result = subprocess.run(command, input=None if body is None else json.dumps(body),
                            text=True, capture_output=True, check=False)
    if result.returncode:
        # Error bodies can contain untrusted content. Keep the hold bounded.
        raise Hold(f"GitHub {method} {path.split('?')[0]} failed; no bypass attempted")
    return json.loads(result.stdout) if result.stdout else None


def candidate(pr: dict) -> bool:
    return (pr.get("state") == "open" and not pr.get("draft")
            and pr.get("head", {}).get("ref") == BRANCH
            and (pr.get("head", {}).get("repo") or {}).get("full_name") == REPO
            and pr.get("base", {}).get("ref") == "master"
            and (pr.get("base", {}).get("repo") or {}).get("full_name") == REPO)


def latest_ci(runs: list[dict], head: str) -> dict | None:
    eligible = [r for r in runs if r.get("path") == ".github/workflows/ci.yml"
                and r.get("event") == "pull_request" and r.get("head_sha") == head
                and (r.get("head_repository") or {}).get("full_name") == REPO]
    return max(eligible, key=lambda r: r["id"], default=None)


def require_checks(runs: list[dict], head: str) -> None:
    latest = latest_ci(runs, head)
    if not latest or latest.get("status") != "completed" or latest.get("conclusion") != "success":
        raise Hold("The latest CI run for this exact PR head has not passed")


def ci_failed(runs: list[dict], head: str) -> bool:
    latest = latest_ci(runs, head)
    return bool(latest and latest.get("status") == "completed"
                and latest.get("conclusion") != "success")


def tree(ref: str) -> dict[str, tuple[str, str, str]]:
    entries = {}
    for record in git("ls-tree", "-r", "-z", f"{ref}:skills").split(b"\0"):
        if not record:
            continue
        metadata, name = record.split(b"\t", 1)
        mode, kind, oid = metadata.decode("ascii").split()
        if kind != "blob" or mode not in ("100644", "100755"):
            raise Hold("Mirror contains a symlink or non-file entry")
        entries[name.decode("utf-8")] = (mode, kind, oid)
    if not entries:
        raise Hold("Canonical or mirror skills tree is empty")
    return entries


def verify_content(source: str, head: str, base: str) -> None:
    # Three-dot diff measures PR-authored changes even when master moved.
    paths = git("diff", "--name-only", "-z", f"{base}...{head}").split(b"\0")
    changed = [p for p in paths if p]
    if not changed or any(not p.startswith(b"skills/") for p in changed):
        raise Hold("PR must change only the skills mirror")
    canonical, mirror = tree(source), tree(head)
    canonical.pop(MANIFEST, None)
    manifest = mirror.pop(MANIFEST, None)
    if canonical != mirror:
        raise Hold("Mirror differs from canonical master (including attestations and file modes)")
    if not manifest or manifest[0] != "100644":
        raise Hold("Mirror manifest is missing or executable")
    lines = []
    for name, (_, _, oid) in sorted(canonical.items()):
        if Path(name).name == MANIFEST or ".attestations" in Path(name).parts:
            continue
        digest = hashlib.sha256(git("cat-file", "blob", oid)).hexdigest()
        lines.append(f"{digest}  {name}")
    body = "\n".join(lines)
    aggregate = hashlib.sha256(body.encode()).hexdigest()
    expected = f"{HEADER}# aggregate: {aggregate}\n{body}\n".encode()
    if git("cat-file", "blob", manifest[2]) != expected:
        raise Hold("Mirror manifest does not match independently computed canonical content")


def deliver(number: int, *, apply: bool) -> str:
    pr = api(f"pulls/{number}")
    if not candidate(pr):
        raise Hold("PR is not an open, ready mirror from the owned automation branch")
    if any(label["name"] in HOLD_LABELS for label in pr.get("labels", [])):
        raise Vetoed("A maintainer hold label is present")
    head = pr["head"]["sha"]
    # A pull's base.sha can remain at its original snapshot after master moves.
    # Read the actual branch for ancestry, fetch validation and race checks.
    base = api("branches/master")["commit"]["sha"]
    runs = api(f"actions/runs?event=pull_request&head_sha={head}&per_page=100")
    # A failed head is still verified below; it may only be re-tested on a
    # newer base, never merged. Pending or missing CI holds here.
    failed = ci_failed(runs["workflow_runs"], head)
    if not failed:
        require_checks(runs["workflow_runs"], head)
    # Fixed remotes/refspecs only. Fetch data, never check out or import PR code.
    git("fetch", "--quiet", "--no-tags", "origin",
        f"+refs/pull/{number}/head:refs/mirror/head", "+refs/heads/master:refs/mirror/base")
    git("fetch", "--quiet", "--no-tags", SOURCE, "+refs/heads/master:refs/mirror/source")
    if git("rev-parse", "refs/mirror/head").decode().strip() != head:
        raise Hold("PR head moved while fetching; the next CI completion will retry")
    if git("rev-parse", "refs/mirror/base").decode().strip() != base:
        raise Hold("Plugin base moved while fetching; re-evaluate against its new head")
    source = git("rev-parse", "refs/mirror/source").decode().strip()
    verify_content(source, head, base)
    # Re-read holds and both refs immediately before a write. GitHub's merge
    # SHA and strict required-check rules are the final concurrent-write guards.
    fresh = api(f"pulls/{number}")
    if (not candidate(fresh) or fresh["head"]["sha"] != head
            or fresh["base"]["sha"] != pr["base"]["sha"]
            or api("branches/master")["commit"]["sha"] != base
            or fresh.get("labels") != pr.get("labels")):
        raise Hold("PR state changed during verification")
    behind = subprocess.run(["git", "merge-base", "--is-ancestor", base, head]).returncode
    if behind not in (0, 1):
        raise Hold("Could not establish base ancestry")
    if failed:
        # A mirror that failed on an older base may already be fixed by master
        # (e.g. a plugin test updated after a canonical edit). Without this, a
        # red head is never re-tested and waits for the next canonical change.
        # Updating makes the head contain master, so this fires once per base
        # move; red on the current base stays held.
        if not behind:
            stuck = Stuck("CI failed on the current base; the mirror needs a fix on master")
            stuck.head = head  # Reported only while this is still the PR head.
            raise stuck
        if not apply:
            return f"#{number} failed CI on an older base; action=update base and re-run CI"
        api(f"pulls/{number}/update-branch", "PUT", {"expected_head_sha": head})
        return f"Updated #{number}: CI failed on an older base; re-running on current master"
    if not apply:
        return f"Verified #{number} at {head}; canonical {source}; action={'update base' if behind else 'merge'}"
    if behind:
        api(f"pulls/{number}/update-branch", "PUT", {"expected_head_sha": head})
        return f"Updated #{number} to the current base; waiting for new CI before merging"
    run_id = os.environ.get("GITHUB_RUN_ID", "")
    provenance = (f"https://github.com/{REPO}/actions/runs/{run_id}"
                  if run_id.isdigit() else "local verified-delivery helper")
    result = api(f"pulls/{number}/merge", "PUT", {
        "sha": head, "merge_method": "squash",
        "commit_title": f"chore(skills): deliver verified canonical mirror (#{number})",
        "commit_message": f"Verified byte mirror of cirwel/unitares at {source}.\n"
                          f"PR head: {head}\nDelivery: {provenance}",
    })
    if not result.get("merged"):
        raise Hold("GitHub did not merge the verified head; protections remain in force")
    return f"Merged #{number}: canonical {source}, PR head {head}, merge {result['sha']}"


def head_age_seconds(head: str) -> float:
    # The commit's own date. The sync and update-branch both commit as they
    # push, so this is when the head arrived to within a few seconds.
    stamp = api(f"commits/{head}")["commit"]["committer"]["date"]
    pushed = datetime.fromisoformat(stamp.replace("Z", "+00:00"))
    return (datetime.now(timezone.utc) - pushed).total_seconds()


def stuck_issues() -> list[dict]:
    issues = api(f"issues?state=open&labels={STUCK_LABEL}&per_page=100")
    # The issues endpoint also lists pull requests; those are never ours.
    # Ours only: opened by an App under this exact title. The label and the
    # marker alone could match an issue a person wrote about a past incident.
    return [i for i in issues if "pull_request" not in i
            and (i.get("user") or {}).get("type") == "Bot" and i.get("title") == STUCK_TITLE
            and STUCK_MARKER in (i.get("body") or "")]


def report_stuck(number: int | None, hold: Hold | None, *, delivered: bool) -> str | None:
    """Keep one issue open while the mirror is stuck. Called only with --apply."""
    if hold is None:
        if not delivered:
            return None  # A branch update is progress, but the mirror has not landed.
        closed = stuck_issues()
        for issue in closed:
            api(f"issues/{issue['number']}", "PATCH", {"state": "closed", "state_reason": "completed"})
        return f"Closed stuck-mirror issue #{closed[0]['number']}" if closed else None
    if isinstance(hold, Vetoed):
        return None
    head = ""
    if number:
        # Delivery's reads are stale by now. Report only what is still true:
        # a head pushed since, or a hold label added since, is the next run's.
        current = api(f"pulls/{number}")
        head = current["head"]["sha"]
        if any(label["name"] in HOLD_LABELS for label in current.get("labels", [])):
            return None
        if getattr(hold, "head", head) != head:
            return None
    if not isinstance(hold, Stuck) and (not head or head_age_seconds(head) < STUCK_AFTER_SECONDS):
        return None
    subject = f"#{number}" if number else "the mirror pull requests"
    # The key keeps hourly runs quiet: the issue is rewritten only when the
    # head or the reason changes. Hold text is fixed wording from this file.
    key = f"<!-- stuck-key: {head}:{hold} -->"
    body = (f"{STUCK_MARKER}\n{key}\n"
            f"Verified mirror delivery cannot land {subject}.\n\n"
            f"- Reason: {hold}\n"
            f"- Head: `{head or 'not established'}`\n\n"
            "Canonical skill text is ahead of the bundled mirror until this clears. "
            "If CI failed or was cancelled, read that run on the pull request: re-run it, "
            "or fix the cause on `master`; delivery re-tests the mirror once `master` moves. "
            "This issue closes itself when the mirror lands.\n")
    existing = stuck_issues()
    if existing:
        if key in existing[0]["body"]:
            return f"Stuck-mirror issue #{existing[0]['number']} is already current"
        api(f"issues/{existing[0]['number']}", "PATCH", {"body": body})
        return f"Updated stuck-mirror issue #{existing[0]['number']}"
    try:
        api("labels", "POST", {"name": STUCK_LABEL, "color": "D93F0B",
                               "description": "Opened by a CI audit/collector"})
    except Hold:
        pass  # The label already exists.
    issue = api("issues", "POST", {"title": STUCK_TITLE,
                                   "labels": [STUCK_LABEL], "body": body})
    return f"Opened stuck-mirror issue #{issue['number']}"


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--pr", type=int)
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args(argv)
    number, hold, delivered = None, None, False
    numbers: list[int] = []
    try:
        if args.pr:
            numbers = [args.pr]
        else:
            prs = api(f"pulls?state=open&head=cirwel:{BRANCH}&base=master&per_page=100")
            numbers = [p["number"] for p in prs if candidate(p)]
            # Only an empty branch means nothing is waiting. A mirror PR turned
            # back into a draft is still open and still undelivered.
            delivered = not prs
        if len(numbers) > 1:
            raise Stuck("Multiple mirror PRs require reconciliation")
        if numbers:
            number = numbers[0]
            messages = [deliver(number, apply=args.apply)]
            delivered = messages[0].startswith("Merged ")
        else:
            messages = ["No open mirror PR to deliver"]
        status = 0
    except Hold as exc:
        messages, status, hold = [f"Mirror delivery held: {exc}"], 1, exc
    except (KeyError, ValueError):
        hold = Hold("GitHub returned an unexpected response; no merge attempted")
        messages, status = [f"Mirror delivery held: {hold}"], 1
    if args.apply:
        try:
            note = report_stuck(number, hold, delivered=delivered)
        except Exception:  # noqa: BLE001
            # Reporting must never change what delivery decided or hide its
            # result, whatever goes wrong here.
            note = "The stuck-mirror issue could not be read or written"
        if note:
            messages.append(note)
    for message in messages:
        print(message)
    if os.environ.get("GITHUB_STEP_SUMMARY"):
        with open(os.environ["GITHUB_STEP_SUMMARY"], "a") as summary:
            summary.write("\n".join(messages) + "\n")
    return status


if __name__ == "__main__":
    sys.exit(main())
